INSERT INTO public."Crafts" ("CraftId", "ProductName", "Address", "Prefecture", "Latitude", "Longitude", "Image", "Description", "CreateAt", "Category", "Certification", "Features", "ProductionAreas", "Reading") VALUES
('7fe0bae4-0d02-48c4-b5fc-120779ea089f', '常滑焼', '常滑市', '愛知県', 34.8853, 136.8438, 'https://upload.wikimedia.org/wikipedia/commons/d/dd/Large_jar%2C_Tokoname_ware%2C_Japan%2C_Heian_period%2C_1100s_AD%2C_natural_glaze_-_Tokyo_National_Museum_-_Tokyo%2C_Japan_-_DSC08941.jpg', '愛知県常滑市を中心に作られる日本六古窯の一つに数えられる陶器。赤みを帯びた「朱泥」と呼ばれる急須が特に有名で、鉄分を多く含む土でお茶の味をまろやかにするといわれる。平安時代末期から続く1000年近い歴史を持つ。', now(), '陶磁器', '経済産業大臣指定伝統的工芸品', '{日本六古窯の一つ,鉄分を含む赤土朱泥の急須,お茶の味をまろやかにする,平安時代から続く歴史}', '{常滑市}', 'とこなめやき'),
('a63841b7-fde7-459e-b89f-c0c8bc0fb28b', '瀬戸焼', '瀬戸市', '愛知県', 35.2241, 137.0864, 'https://upload.wikimedia.org/wikipedia/commons/b/b8/Yellow_Seto_ware_water_jar%2C_17th_century%2C_Metropolitan_Museum_of_Art%2C_17.118.81a%2Cb.JPG', '愛知県瀬戸市を中心に作られる陶磁器で、日本六古窯の一つ。「せともの」という言葉の語源になったとされるほど広く親しまれ、多彩な釉薬と成形技法を用いた幅広い製品づくりが特徴。1000年以上の歴史を持つ。', now(), '陶磁器', '経済産業大臣指定伝統的工芸品', '{せとものの語源となった産地,多彩な釉薬と成形技法,日用食器から美術品まで幅広い,1000年以上続く陶磁器の里}', '{瀬戸市}', 'せとやき'),
('bf2f4149-a849-4529-8512-5e1c89d40a69', '有松・鳴海絞り', '名古屋市緑区有松', '愛知県', 35.0682, 136.9714, 'https://upload.wikimedia.org/wikipedia/commons/5/58/Arimatsu_Shibori%E9%B9%BF%E3%81%AE%E5%AD%90%E7%B5%9E.jpg', '愛知県名古屋市の有松・鳴海地区に伝わる絞り染め。布を糸でくくったり縫ったりしてから染めることで、多彩な絞り模様を生み出す。江戸時代初期に始まり、100種類以上の技法があるとされる。', now(), '染織品', '経済産業大臣指定伝統的工芸品', '{100種類以上の絞り技法,布をくくって染める伝統技法,浴衣や手ぬぐいが代表的,江戸時代から続く町並みと共に発展}', '{名古屋市緑区有松,名古屋市緑区鳴海}', 'ありまつ・なるみしぼり'),
('8f417b76-a8a9-443f-89de-7f9c5af46885', '豊橋筆', '豊橋市', '愛知県', 34.7692, 137.3914, 'https://upload.wikimedia.org/wikipedia/commons/2/24/Toyohashi_hude.JPG', '愛知県豊橋市で作られる書道用の筆。動物の毛を一本一本選別し、穂先を作る「精毛」という工程に高い技術を要する。江戸時代後期に始まり、現在も国内有数の筆の産地として知られる。', now(), '文具', '経済産業大臣指定伝統的工芸品', '{動物の毛を厳選する精毛技術,滑らかな書き味を生む穂先,国内有数の高級筆の産地,江戸時代後期から続く歴史}', '{豊橋市}', 'とよはしふで'),
('dd3d1501-aae4-416c-baa0-77aa1175bb14', '駿河竹千筋細工', '静岡市', '静岡県', 34.9756, 138.3828, 'https://upload.wikimedia.org/wikipedia/commons/c/c7/Suruga_Bamboo_Craft_03_%EF%BC%88%E9%A7%BF%E6%B2%B3%E7%AB%B9%E5%8D%83%E7%AD%8B%E7%B4%B0%E5%B7%A5%EF%BC%89.jpg', '静岡県静岡市を中心に作られる竹細工。丸く削った細い竹ひごを何本も組み合わせて編み上げる「千筋」の技法が特徴で、繊細で美しい造形の虫かごや花器などが作られる。江戸時代末期から続く。', now(), '竹工品', '経済産業大臣指定伝統的工芸品', '{丸ひごを組む千筋の技法,繊細で立体的な造形美,虫かごや花器が代表的,江戸時代末期から続く竹工芸}', '{静岡市}', 'するがたけせんすじざいく'),
('cea9d4a2-1115-47ad-a64c-5d0306543848', '駿河雛人形', '静岡市', '静岡県', 34.9756, 138.3828, 'https://upload.wikimedia.org/wikipedia/commons/e/e7/Suruga_Hina_Ningyo_%EF%BC%88%E9%A7%BF%E6%B2%B3%E9%9B%9B%E4%BA%BA%E5%BD%A2%EF%BC%89.jpg', '静岡県静岡市を中心に作られる雛人形。頭・髪付け・手足・小道具など多くの工程が分業で行われ、それぞれの職人の技が結集して作られる。徳川家康による駿府城築城の際に職人が集まったことが起源とされる。', now(), '人形', '経済産業大臣指定伝統的工芸品', '{分業制による高い専門技術,職人の技が結集した精巧な仕上がり,徳川家康ゆかりの歴史,全国有数の雛具・雛人形の産地}', '{静岡市}', 'するがひなにんぎょう'),
('24386dd7-7550-4492-964d-b2e3dbdff984', '伊賀焼', '伊賀市', '三重県', 34.7666, 136.1289, 'https://upload.wikimedia.org/wikipedia/commons/0/02/Flower_Vase_with_Lugs%2C_Iga_ware%2C_Edo_period%2C_17th_century_-_Tokyo_National_Museum_-_DSC05283.JPG', '三重県伊賀市を中心に作られる陶器。耐火性に優れた土を用いており、直火にかけられる土鍋や食器が特徴。奈良時代から続くとされ、桃山時代には茶陶としても高く評価された。', now(), '陶磁器', '経済産業大臣指定伝統的工芸品', '{耐火性に優れた土を使用,直火可能な土鍋が代表的,桃山時代には茶陶として評価,奈良時代から続く歴史}', '{伊賀市}', 'いがやき'),
('b2686dc2-30b6-4e6b-a20a-4edbd69f68f9', '四日市萬古焼', '四日市市', '三重県', 34.9647, 136.6222, 'https://upload.wikimedia.org/wikipedia/commons/c/cf/Found_MUJI_Bankoyaki_%286910159991%29.jpg', '三重県四日市市を中心に作られる陶器。耐熱性に優れた土鍋が全国的なシェアを誇り、江戸時代中期に始まった。軽くて丈夫な急須も代表的な製品として知られる。', now(), '陶磁器', '経済産業大臣指定伝統的工芸品', '{耐熱性に優れた土鍋が全国シェア1位,軽くて丈夫な急須も人気,江戸時代中期から続く歴史,実用性を重視したものづくり}', '{四日市市}', 'よっかいちばんこやき'),
('b1fc91a2-a265-4d4a-9030-71e163b3adcc', '伊勢型紙', '鈴鹿市', '三重県', 34.8807, 136.5852, 'https://upload.wikimedia.org/wikipedia/commons/c/c8/Ise_Katagami_%28%E4%BC%8A%E5%8B%A2%E5%9E%8B%E7%B4%99%29.png', '三重県鈴鹿市白子地区を中心に作られる、着物の生地を染めるための型紙。和紙を柿渋で貼り合わせた地紙に、彫刻刀で精緻な文様を彫り抜く。室町時代から続くとされ、全国の染物産地に型紙を供給してきた。', now(), '型紙', '経済産業大臣指定伝統的工芸品', '{彫刻刀で彫る精緻な文様,柿渋で貼り合わせた丈夫な地紙,全国の染物産地を支えた技術,室町時代から続く歴史}', '{鈴鹿市}', 'いせかたがみ'),
('48c56365-a908-42d0-8ac0-408ff40b6e63', '伊賀くみひも', '伊賀市', '三重県', 34.7666, 136.1289, 'https://upload.wikimedia.org/wikipedia/commons/a/a6/Atang_Tshikare_Iga-Kumihimo_Craft_x_Tech_Tokai_Project.jpg', '三重県伊賀市を中心に作られる組紐。絹糸などを組み台で編み上げて紐にする技術で、帯締めや羽織紐として使われる。江戸時代に武具や茶道具の飾り紐として発展し、全国有数の組紐の産地となっている。', now(), '組紐', '経済産業大臣指定伝統的工芸品', '{組み台で糸を編み上げる伝統技術,帯締めや羽織紐に使用,全国有数の組紐の産地,江戸時代の武具から発展}', '{伊賀市}', 'いがくみひも');
